import org.eclipse.rdf4j.sail.lmdb.LmdbStore;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

import jdk.jfr.Recording;
import jdk.jfr.consumer.RecordedEvent;
import jdk.jfr.consumer.RecordingFile;

class NativeStrategyDecisionDiagnosticsTest {

	private static final String EVENT = "org.eclipse.rdf4j.lmdb.NativeStrategyDecision";
	private static final String QUERY = "SELECT ?s ?o WHERE { ?s <urn:p> ?o . ?o <urn:q> ?x }";

	@TempDir
	File dataDir;

	private SailRepository repository;

	@BeforeEach
	void setUp() {
		repository = new SailRepository(new LmdbStore(dataDir,
				new LmdbStoreConfig("spoc,posc").setNativeEvaluationEnabled(true)));
		repository.init();
		ValueFactory vf = SimpleValueFactory.getInstance();
		try (SailRepositoryConnection connection = repository.getConnection()) {
			connection.begin(IsolationLevels.NONE);
			for (int i = 0; i < 200; i++) {
				connection.add(vf.createIRI("urn:s" + i), vf.createIRI("urn:p"), vf.createIRI("urn:o" + i));
				connection.add(vf.createIRI("urn:o" + i), vf.createIRI("urn:q"), vf.createIRI("urn:x" + i));
			}
			connection.commit();
		}
	}

	@AfterEach
	void tearDown() {
		repository.shutDown();
	}

	private static String metric(GenericPlanNode node, String name) {
		if (node == null) {
			return null;
		}
		String value = node.getStringMetricActual(name);
		if (value != null || node.getPlans() == null) {
			return value;
		}
		return node.getPlans()
				.stream()
				.map(child -> metric(child, name))
				.filter(v -> v != null)
				.findFirst()
				.orElse(null);
	}

	@Test
	void everyDecisionIsOneExplainMetricWithItsCandidatesAndTheWinnersReason() {
		try (SailRepositoryConnection connection = repository.getConnection()) {
			GenericPlanNode plan = ((SailTupleQuery) connection.prepareTupleQuery(QUERY))
					.explain(Explanation.Level.Telemetry)
					.toGenericPlanNode();

			String decision = metric(plan, "nativeDecision.ROW.0");

			assertThat(decision).as("the row decision of the join").isNotNull();
			assertThat(decision).startsWith("winner=").contains("; reason=").contains(" WINNER");
			assertThat(decision).contains(" ns (expected ");
			assertThat(metric(plan, "nativeDecisionOutcome")).startsWith("winner=");
		}
	}

	@Test
	void aPriceEliminationIsADeclineWithItsReason() {
		try (SailRepositoryConnection connection = repository.getConnection()) {
			GenericPlanNode plan = ((SailTupleQuery) connection.prepareTupleQuery(QUERY))
					.explain(Explanation.Level.Telemetry)
					.toGenericPlanNode();

			String decision = metric(plan, "nativeDecision.ROW.0");
			if (decision.contains(" eliminated: ")) {
				String reason = decision.substring(decision.indexOf(" eliminated: ") + " eliminated: ".length());
				String first = reason.contains(";") ? reason.substring(0, reason.indexOf(';')) : reason;
				assertThat(metric(plan, "nativeStrategyDeclines")).contains(first);
			}
		}
	}

	@Test
	void aRecordedDecisionCommitsOneEventPerCandidateAndOneWinner() throws Exception {
		Path file = dataDir.toPath().resolveSibling(dataDir.getName() + "-decisions.jfr");
		try (Recording recording = new Recording()) {
			recording.enable(EVENT).withThreshold(Duration.ZERO);
			recording.start();
			try (SailRepositoryConnection connection = repository.getConnection();
					TupleQueryResult result = connection.prepareTupleQuery(QUERY).evaluate()) {
				assertThat(result.stream().count()).isEqualTo(200L);
			}
			recording.stop();
			recording.dump(file);
		}

		List<RecordedEvent> events = RecordingFile.readAllEvents(file)
				.stream()
				.filter(event -> EVENT.equals(event.getEventType().getName()))
				.toList();
		assertThat(events).isNotEmpty();
		Map<String, List<RecordedEvent>> decisions = events.stream()
				.collect(Collectors.groupingBy(
						event -> event.getLong("decisionId") + "/" + event.getInt("rankingRound")));
		for (List<RecordedEvent> decision : decisions.values()) {
			assertThat(decision.stream().filter(event -> event.getBoolean("winner")).count())
					.as("one winner in %s", decision)
					.isEqualTo(1L);
			RecordedEvent winner = decision.stream().filter(event -> event.getBoolean("winner")).findFirst().get();
			assertThat(winner.getBoolean("admitted")).isTrue();
			assertThat(winner.getString("eliminatedBy")).isNull();
			assertThat(winner.getDouble("expectedNanos")).isGreaterThan(0D);
			assertThat(winner.getString("provenance")).isEqualTo("quoted");
			assertThat(winner.getString("reason")).isNotBlank();
			assertThat(winner.getString("accessSource")).isNotBlank();
		}
		assertThat(events.stream().map(event -> event.getString("candidate")).distinct().count())
				.as("every candidate, not only the winner")
				.isGreaterThan(1L);
	}
}
